CREATE TABLE creator_profile(user_id TEXT PRIMARY KEY REFERENCES member(user_id),handle TEXT NOT NULL UNIQUE CHECK(length(handle) BETWEEN 3 AND 24 AND handle NOT GLOB '*[^a-z0-9_-]*'),display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 60),bio TEXT NOT NULL DEFAULT '' CHECK(length(bio)<=500),avatar_hue INTEGER NOT NULL DEFAULT 0 CHECK(avatar_hue BETWEEN 0 AND 359),links TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(links) AND json_array_length(links)<=3),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE creator_follow(follower_id TEXT NOT NULL REFERENCES member(user_id),creator_id TEXT NOT NULL REFERENCES member(user_id),created_at INTEGER NOT NULL,PRIMARY KEY(follower_id,creator_id),CHECK(follower_id<>creator_id));
CREATE INDEX creator_follow_creator ON creator_follow(creator_id,created_at);
CREATE TABLE favorite(user_id TEXT NOT NULL REFERENCES member(user_id),asset_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,asset_id));
CREATE INDEX favorite_asset ON favorite(asset_id);
CREATE TABLE model_comment(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES asset_version(id),author_id TEXT NOT NULL REFERENCES member(user_id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','hidden','deleted')),moderated_by TEXT REFERENCES member(user_id),moderation_reason TEXT,created_at INTEGER NOT NULL);
CREATE INDEX model_comment_version ON model_comment(version_id,created_at);
CREATE INDEX model_comment_author ON model_comment(author_id,created_at);
CREATE TABLE comment_report(id TEXT PRIMARY KEY,comment_id TEXT NOT NULL REFERENCES model_comment(id),reporter_id TEXT NOT NULL REFERENCES member(user_id),reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','hidden','dismissed')),resolved_by TEXT REFERENCES member(user_id),created_at INTEGER NOT NULL,UNIQUE(comment_id,reporter_id));
CREATE INDEX comment_report_reporter ON comment_report(reporter_id,created_at);
CREATE TABLE version_lineage(version_id TEXT PRIMARY KEY REFERENCES asset_version(id),parent_asset_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX version_lineage_parent ON version_lineage(parent_asset_id);
CREATE TABLE download_credit(user_id TEXT NOT NULL REFERENCES member(user_id),asset_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,asset_id));
CREATE INDEX download_credit_asset ON download_credit(asset_id,created_at);
CREATE TABLE notification_cursor(user_id TEXT PRIMARY KEY REFERENCES member(user_id),read_before INTEGER NOT NULL);
CREATE INDEX vote_asset ON vote(asset_id,created_at);
CREATE INDEX vote_user ON vote(user_id,created_at);
CREATE INDEX asset_version_contributor ON asset_version(contributor_id,state);
CREATE INDEX audit_event_actor_action ON audit_event(actor_id,action,created_at);
CREATE TRIGGER vote_no_self BEFORE INSERT ON vote WHEN EXISTS(SELECT 1 FROM asset_version WHERE asset_id=NEW.asset_id AND contributor_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'self_vote_forbidden'); END;
CREATE TRIGGER download_credit_no_self BEFORE INSERT ON download_credit WHEN EXISTS(SELECT 1 FROM asset_version WHERE asset_id=NEW.asset_id AND contributor_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'self_download_credit_forbidden'); END;
